<script lang="ts">
  import type { AutomationApi, AutomationSnapshot, AutomationEntity } from '../api/automation';
  let { api, snapshot, refresh, openHome }: { api: AutomationApi; snapshot: AutomationSnapshot | null; refresh: () => Promise<void>; openHome: () => void } = $props();
  let url = $state(''); let token = $state(''); let query = $state(''); let area = $state('');
  let busy = $state(false); let message = $state(''); let error = $state('');
  let pending = $state<{ entity: AutomationEntity; action: 'turn_on' | 'turn_off' } | null>(null);
  let powerDialog: HTMLDialogElement;
  $effect(() => { if (pending && powerDialog && !powerDialog.open) powerDialog.showModal(); if (!pending && powerDialog?.open) powerDialog.close(); });
  const connected = $derived(snapshot?.status === 'connected');
  const devices = $derived((snapshot?.devices ?? []).filter(d => (!area || d.area === area || d.entities.some(e => e.area === area)) && `${d.name} ${d.manufacturer ?? ''} ${d.model ?? ''} ${d.area ?? ''} ${d.mac_addresses.join(' ')} ${d.entities.map(e => e.name).join(' ')}`.toLowerCase().includes(query.toLowerCase())));
  const enabledIds = $derived((snapshot?.devices ?? []).flatMap(d => d.entities.filter(e => e.control_enabled).map(e => e.entity_id)));
  async function perform(action: () => Promise<unknown>) {
    if (busy) return; busy = true; error = ''; message = '';
    try { await action(); await refresh(); } catch (e) { error = e instanceof Error ? e.message : 'The operation could not be completed.'; } finally { busy = false; }
  }
  function connect() { const credential = token; token = ''; void perform(() => api.connect(url.trim(), credential)); }
  function permission(entity: AutomationEntity) {
    const ids = entity.control_enabled ? enabledIds.filter(id => id !== entity.entity_id) : [...enabledIds, entity.entity_id];
    void perform(() => api.permissions(ids));
  }
  async function confirmPower() {
    const command = pending; pending = null; if (!command) return;
    await perform(async () => { const receipt = await api.command(command.entity, command.action); message = receipt.detail; });
  }
  const seen = (value: string) => new Date(value).toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' });
</script>

<section class="automation-view" aria-labelledby="automation-heading">
  <div class="view-heading"><div><p class="kicker">HOME / CONNECTIONS & CONTROL</p><h1 id="automation-heading">Your home, connected.</h1><p class="muted">Understand each device, find its room, and control the things you choose.</p></div><button class="chrome-button" onclick={openHome}>Open home map →</button></div>
  <div class="summary-grid"><article class="summary"><span class="kicker">HOME ASSISTANT</span><strong class:online={connected}>{connected ? 'Connected' : snapshot?.status.replaceAll('_', ' ') ?? 'Connecting to collector'}</strong><p>{snapshot?.detail ?? 'Waiting for the local service.'}</p></article><article class="summary"><span class="kicker">IMPORTED DEVICES</span><strong>{snapshot?.devices.length ?? '—'}</strong><p>Automation inventory, with names and identity from Home Assistant.</p></article><article class="summary"><span class="kicker">YOUR CONTROL PERMISSIONS</span><strong>{enabledIds.length}</strong><p>Enabled entities. Permissions clear whenever the connection is lost.</p></article></div>
  {#if error}<p class="notice error" role="alert">{error}</p>{/if}
  {#if message}<p class="notice" role="status">{message}</p>{/if}
  <div class="notice mqtt-state"><strong>MQTT hub · {snapshot?.mqtt?.status.replaceAll('_', ' ') ?? 'Checking'}</strong><span>{snapshot?.mqtt?.detail ?? 'Waiting for the local service.'}</span></div>
  <details class="connection-panel" open={!connected}>
    <summary>Home Assistant connection</summary>
    <p>Use a dedicated Home Assistant account. Its token stays in service memory for this session; reconnect after restarting NeonHearth.</p>
    <form onsubmit={(event) => { event.preventDefault(); connect(); }}>
      <label>Home Assistant address<input type="url" bind:value={url} required placeholder="https://homeassistant.your-tailnet.ts.net" autocomplete="url" maxlength="512" /></label>
      <label>Access token<input type="password" bind:value={token} required minlength="16" maxlength="4096" autocomplete="off" spellcheck="false" /></label>
      <button class="chrome-button primary" disabled={busy || !url || !token}>Connect & import</button>
      {#if snapshot?.source}<button class="chrome-button" type="button" disabled={busy || snapshot.status === 'disconnected'} onclick={() => void perform(() => api.disconnect())}>Disconnect</button>{/if}
    </form>
    <p class="muted">HTTPS with a trusted certificate is required on your network. A local test instance may use http://127.0.0.1. Imported room names are location hints; place devices yourself to establish their position.</p>
  </details>
  <div class="filters"><label>Find a device<input bind:value={query} placeholder="Name, model, MAC address, or room" /></label><label>Room<select bind:value={area}><option value="">All rooms</option>{#each snapshot?.areas ?? [] as name}<option value={name}>{name}</option>{/each}</select></label><button class="chrome-button" onclick={() => void perform(refresh)} disabled={busy}>Refresh</button></div>
  {#if !devices.length}<div class="empty-state"><strong>{snapshot?.devices.length ? 'No matching devices' : 'Start with Home Assistant'}</strong><p class="muted">Connect above to import devices and rooms. Your network discoveries remain in Devices.</p></div>{/if}
  <div class="automation-devices">{#each devices as device (device.device_id)}<article class="automation-device">
    <div class="device-title"><span class="device-icon" aria-hidden="true">⌂</span><div><h2>{device.name}</h2><p>{device.manufacturer ?? 'Manufacturer unreported'}{device.model ? ` · ${device.model}` : ''}</p></div><span class="room-label">{device.area ?? 'Room unassigned'}</span></div>
    {#if device.mac_addresses.length}<p class="mac">{device.mac_addresses.join(' · ')}</p>{/if}
    <p class="first-seen">First imported {seen(device.first_seen_at)} · {device.entities.length} {device.entities.length === 1 ? 'entity' : 'entities'}</p>
    <div class="entity-list">{#each device.entities as entity (entity.entity_id)}<div class="entity"><div><strong>{entity.name}</strong><small>{entity.platform ?? 'Home Assistant'}{entity.area ? ` · ${entity.area}` : ''}</small></div><span class="state" class:on={connected && entity.state === 'on'}>{connected ? entity.state : 'unknown'}</span>{#if entity.power_capable}<div class="entity-controls"><button class="permission" onclick={() => permission(entity)} disabled={busy || !connected} aria-pressed={entity.control_enabled}>{entity.control_enabled ? 'Revoke control' : 'Allow power control'}</button><button class="chrome-button" disabled={busy || !connected || !entity.control_enabled || !['on','off'].includes(entity.state) || !entity.last_changed} onclick={() => pending = { entity: { ...entity }, action: entity.state === 'on' ? 'turn_off' : 'turn_on' }}>{entity.state === 'on' ? 'Turn off' : 'Turn on'}</button></div>{:else}<span class="read-only">Observation only</span>{/if}</div>{/each}</div>
  </article>{/each}</div>
  <details class="connection-panel"><summary>Protocols & software integration</summary><div class="protocol-grid"><article><h3>Network discovery</h3><p>The network collector observes your host's network visibility. “First seen” is when this monitor discovered a device; an exact Wi-Fi join requires access-point events.</p></article><article><h3>Home automation</h3><p>Home Assistant bridges its configured Zigbee, Z-Wave, Matter, Bluetooth, ESPHome, and vendor integrations. Compatible controllers and radios are required where applicable.</p></article><article><h3>MQTT hub</h3><p>The included Mosquitto setup uses authenticated clients and topic permissions. The application launcher starts the local hub; network clients require a TLS listener.</p></article><article><h3>Other applications</h3><p>Versioned local JSON APIs and the existing scoped read APIs expose inventory and events. Integration credentials do not inherit appliance-control permission.</p></article></div></details>
  <dialog bind:this={powerDialog} class="confirm-dialog" aria-labelledby="power-title" oncancel={() => pending = null}>{#if pending}<p class="kicker">CONFIRM POWER ACTION</p><h2 id="power-title">{pending.action === 'turn_off' ? 'Turn off' : 'Turn on'} {pending.entity.name}?</h2><p>This sends a real command to <strong>{pending.entity.entity_id}</strong> through Home Assistant. Check what is connected to this device before continuing.</p><div><button class="chrome-button" onclick={() => pending = null}>Cancel</button><button class="chrome-button primary" onclick={() => void confirmPower()}>Confirm {pending.action === 'turn_off' ? 'turn off' : 'turn on'}</button></div>{/if}</dialog>
</section>
<style>
  .mqtt-state { display:flex;flex-wrap:wrap;gap:8px 20px;align-items:center }.mqtt-state span { color:var(--ink-mute) }
  .automation-view { display:grid; gap:22px; min-width:0 }.view-heading { align-items:center; gap:16px; flex-wrap:wrap }.view-heading h1 { margin:8px 0 }.chrome-button { min-height:42px;padding:10px 16px;border:1px solid var(--line);border-radius:12px;color:var(--ink);background:var(--surface-2);font:500 13px var(--font-body);cursor:pointer }.chrome-button.primary { border-color:var(--ember);color:var(--ember) }button:disabled { opacity:.5;cursor:not-allowed }.summary-grid { display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px }.summary,.connection-panel,.automation-device { background:var(--panel);border:1px solid var(--line);border-radius:var(--radius-card);padding:20px }.summary strong { display:block;font:500 30px var(--font-display);margin:13px 0;text-transform:capitalize }.summary strong.online { color:var(--ember) }.summary p,.connection-panel p { color:var(--ink-mute);font-size:13px;line-height:1.6;margin-bottom:0 }.connection-panel summary { cursor:pointer;font-weight:600 }.connection-panel form { display:flex;flex-wrap:wrap;gap:14px;align-items:end;margin:18px 0 }label { display:grid;gap:7px;color:var(--ink-mute);font-size:12px }.connection-panel label { flex:1;min-width:200px }input,select { min-height:42px;border:1px solid var(--line);background:var(--surface-2);color:var(--ink);border-radius:10px;padding:9px 12px;min-width:0;font:14px var(--font-body) }.filters { display:flex;gap:12px;align-items:end;flex-wrap:wrap }.filters label:first-child { flex:1;min-width:200px }.filters select { min-width:160px }.automation-devices { display:grid;gap:14px }.device-title { display:flex;align-items:center;gap:12px }.device-title>div { min-width:0;overflow-wrap:anywhere }.device-title h2 { font-size:18px;margin:0 0 5px }.device-title p { color:var(--ink-mute);font-size:12px;margin:0 }.device-icon { display:grid;place-items:center;width:44px;height:44px;border-radius:14px;border:1px solid var(--line);color:var(--ember);font-size:25px;flex-shrink:0 }.room-label { flex-shrink:0;margin-left:auto;color:var(--ember);font-size:12px;max-width:35%;overflow-wrap:anywhere }.mac,.first-seen { color:var(--ink-mute);font:11px var(--font-mono);line-height:1.6 }.entity { display:flex;align-items:center;gap:14px;padding:14px 0;border-top:1px solid var(--line);flex-wrap:wrap }.entity>div:first-child { flex:1;min-width:140px;overflow-wrap:anywhere }.entity strong { font-size:13px }.entity small { display:block;color:var(--ink-mute);font-size:11px;margin-top:5px }.entity-controls { display:flex;gap:8px;align-items:center }.permission { background:none;border:0;color:var(--ink-mute);font-size:11px;cursor:pointer;min-height:40px }.state { font:12px var(--font-mono);padding:6px 10px;border:1px solid var(--line);border-radius:8px;max-width:150px;overflow-wrap:anywhere }.state.on { color:var(--ember) }.read-only { font-size:11px;color:var(--ink-mute) }.notice { border:1px solid var(--ember);border-radius:12px;padding:14px;font-size:13px;line-height:1.6 }.notice.error { border-color:var(--alert);color:var(--alert-text) }.protocol-grid { display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin-top:16px }.protocol-grid h3 { font-size:14px;margin-bottom:5px }.confirm-dialog::backdrop { background:#04050cbb;backdrop-filter:blur(10px) }.confirm-dialog { color:var(--ink);width:calc(100% - 40px);max-width:480px;padding:28px;background:var(--surface-2);border:1px solid var(--line);border-radius:24px;box-shadow:var(--shadow) }.confirm-dialog h2 { font-size:24px;overflow-wrap:anywhere }.confirm-dialog p { line-height:1.7;font-size:14px;overflow-wrap:anywhere }.confirm-dialog>div { display:flex;gap:12px;justify-content:flex-end;margin-top:22px }@media(max-width:700px){.summary-grid,.protocol-grid{grid-template-columns:1fr}.summary{padding:16px}.summary strong{font-size:25px}.connection-panel,.automation-device{padding:16px}.entity-controls{width:100%;justify-content:flex-end}.room-label{max-width:30%}.connection-panel label{min-width:100%;}.filters label{width:100%}}
</style>
